"use client";

import {FormEvent,useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type Job={id:string;title:string;description:string;budget_min_cents:number|null;budget_max_cents:number|null;businesses?:{name?:string}|null};
const demoJobs:Job[]=[
  {id:"d1",title:"Reels-монтажёр",description:"5–7 short-form роликов в неделю.",budget_min_cents:4500000,budget_max_cents:6000000,businesses:{name:"Demo Brand"}},
  {id:"d2",title:"YouTube Shorts",description:"Экспертный talking-head + B-roll.",budget_min_cents:250000,budget_max_cents:350000,businesses:{name:"Creator Studio"}},
  {id:"d3",title:"UGC ads editor",description:"Коммерческие performance-креативы.",budget_min_cents:6000000,budget_max_cents:8000000,businesses:{name:"Growth Team"}},
];

export default function JobBoard({mode,viewerName="Business"}:{mode:"editor"|"business";viewerName?:string}){
  const [jobs,setJobs]=useState<Job[]>([]);
  const [businessId,setBusinessId]=useState<string|null>(null);
  const [message,setMessage]=useState("");
  const [form,setForm]=useState({title:"",description:"",min:"",max:""});

  useEffect(()=>{void load()},[mode]);

  async function load(){
    const supabase=getSupabaseBrowserClient();
    if(!supabase){setJobs(demoJobs);return;}
    const {data:{user}}=await supabase.auth.getUser();
    if(!user){setJobs(demoJobs);return;}

    if(mode==="business"){
      let {data:business}=await supabase.from("businesses").select("id").eq("owner_id",user.id).maybeSingle();
      if(!business){
        const {data:created}=await supabase.from("businesses")
          .upsert({owner_id:user.id,name:viewerName+" Studio"},{onConflict:"owner_id"})
          .select("id")
          .single();
        business=created;
      }
      if(!business){setJobs([]);setMessage("Не удалось создать Business Workspace.");return;}
      setBusinessId(business.id);
      const {data,error}=await supabase.from("jobs").select("id,title,description,budget_min_cents,budget_max_cents").eq("business_id",business.id).order("created_at",{ascending:false});
      if(error){setMessage(error.message);return;}
      setJobs((data||[]) as Job[]);
    }else{
      const {data,error}=await supabase.from("jobs").select("id,business_id,title,description,budget_min_cents,budget_max_cents").eq("status","open").order("created_at",{ascending:false});
      if(error){setMessage(error.message);setJobs(demoJobs);return;}
      const rows=(data||[]) as any[];
      const businessIds=[...new Set(rows.map(j=>j.business_id).filter(Boolean))];
      const {data:brands}=businessIds.length?await supabase.from("public_businesses").select("id,name").in("id",businessIds):{data:[] as any[]};
      const names=Object.fromEntries((brands||[]).map((b:any)=>[b.id,b.name]));
      setJobs(rows.map(j=>({...j,businesses:{name:names[j.business_id]||"Verified Business"}})) as Job[]);
    }
  }

  async function apply(jobId:string){
    const supabase=getSupabaseBrowserClient();
    if(!supabase){setMessage("Demo: заявка принята локально.");return;}
    const {data:{user}}=await supabase.auth.getUser();
    if(!user){setMessage("Войди, чтобы податься.");return;}
    const {error}=await supabase.from("job_applications").upsert({job_id:jobId,editor_id:user.id,status:"applied"},{onConflict:"job_id,editor_id"});
    setMessage(error?error.message:"Заявка отправлена бизнесу.");
  }

  async function create(e:FormEvent){
    e.preventDefault();
    const supabase=getSupabaseBrowserClient();
    if(!supabase||!businessId){setMessage("В demo вакансия не публикуется в базе.");return;}
    const {error}=await supabase.from("jobs").insert({
      business_id:businessId,title:form.title,description:form.description,status:"open",
      budget_min_cents:form.min?Math.round(Number(form.min)*100):null,
      budget_max_cents:form.max?Math.round(Number(form.max)*100):null
    });
    if(error){setMessage(error.message);return;}
    setForm({title:"",description:"",min:"",max:""});setMessage("Вакансия опубликована.");
    await load();
  }

  return <div className="job-board">
    {mode==="business"&&<section className="card"><div className="eyebrow">NEW JOB</div><h3>Опубликовать вакансию</h3><form className="business-form" onSubmit={create}>
      <input required placeholder="Название роли" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/>
      <textarea required placeholder="Задачи, объём, формат работы" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/>
      <div className="split-fields"><input type="number" min="0" placeholder="От, ₽" value={form.min} onChange={e=>setForm({...form,min:e.target.value})}/><input type="number" min="0" placeholder="До, ₽" value={form.max} onChange={e=>setForm({...form,max:e.target.value})}/></div>
      <button className="btn btn-dark">Опубликовать</button>
    </form></section>}

    <section className="grid job-grid">{jobs.map(job=><article className="card job" key={job.id}>
      <small>{mode==="editor"?(job.businesses?.name||"VERIFIED BUSINESS"):"YOUR JOB"}</small>
      <h3>{job.title}</h3><p className="muted">{job.description}</p>
      <b>{budget(job)}</b>
      {mode==="editor"&&<button className="btn btn-dark" onClick={()=>apply(job.id)}>Податься</button>}
    </article>)}</section>
    {message&&<div className="auth-msg">{message}</div>}
  </div>
}

function budget(job:Job){
  const min=job.budget_min_cents?Math.round(job.budget_min_cents/100):null;
  const max=job.budget_max_cents?Math.round(job.budget_max_cents/100):null;
  if(min&&max)return new Intl.NumberFormat("ru-RU").format(min)+"–"+new Intl.NumberFormat("ru-RU").format(max)+" ₽";
  if(min)return "от "+new Intl.NumberFormat("ru-RU").format(min)+" ₽";
  if(max)return "до "+new Intl.NumberFormat("ru-RU").format(max)+" ₽";
  return "Бюджет по договорённости";
}

"use client";

import { useState } from "react";
import { getSupabaseBrowserClient } from "@/lib/supabase-browser";

export default function PayButton({product,label}:{product:"start"|"ai-pro-30";label:string}) {
  const [loading,setLoading]=useState(false);
  const [error,setError]=useState("");

  async function pay(){
    setLoading(true);setError("");
    try{
      const supabase=getSupabaseBrowserClient();
      const session=supabase?(await supabase.auth.getSession()).data.session:null;
      const headers:Record<string,string>={"Content-Type":"application/json"};
      if(session?.access_token)headers.Authorization="Bearer "+session.access_token;

      const r=await fetch("/api/payments/yookassa/create",{
        method:"POST",
        headers,
        body:JSON.stringify({product})
      });
      const data=await r.json();
      if(!r.ok||!data.confirmationUrl)throw new Error(data?.error||"Не удалось создать платёж");
      window.location.href=data.confirmationUrl;
    }catch(e){
      setError(e instanceof Error?e.message:"Ошибка оплаты");
      setLoading(false);
    }
  }

  return <div className="pay-action">
    <button className="btn btn-dark" onClick={pay} disabled={loading}>{loading?"Переходим к оплате…":label}</button>
    {error&&<div className="auth-msg">{error}</div>}
  </div>
}

"use client";
import {useEffect,useMemo,useState} from "react";
import Link from "next/link";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";
import ChallengeCenter from "@/components/challenge-center";
import VideoReview from "@/components/video-review";
import {curriculum} from "@/lib/curriculum";
import BrandBrain from "@/components/brand-brain";
import ClientSimulator from "@/components/client-simulator";
import PortfolioPanel from "@/components/portfolio-panel";
import JobBoard from "@/components/job-board";
import CommunityLeaderboard from "@/components/community-leaderboard";

type Tab="home"|"academy"|"practice"|"coach"|"review"|"arena"|"portfolio"|"jobs"|"community"|"wallet"|"profile"|"business";
type Onboarding={level?:string;software?:string;goal?:string;ageGroup?:string};
type Viewer={
  name:string;
  role:"editor"|"business"|null;
  username?:string|null;
  plan?:string|null;
  aiScore?:number|null;
  onboarding?:Onboarding;
  earningsCents?:number;
  planExpiresAt?:string|null;
  guardianVerified?:boolean;
};

const allTabs:[Tab,string][]=[
  ["home","Главная"],["academy","Академия"],["practice","Практика"],["coach","AI Coach"],["review","AI Review"],
  ["arena","Arena"],["portfolio","Портфолио"],["jobs","Jobs"],["community","Community"],["wallet","Wallet"],["profile","Профиль"],["business","Для бизнеса"]
];

export default function PlatformApp(){
 const [tab,setTab]=useState<Tab>("home");
 const [done,setDone]=useState<string[]>([]);
 const [viewer,setViewer]=useState<Viewer>({name:"Гость",role:null,onboarding:{}});
 const [messages,setMessages]=useState([{from:"ai",text:"Привет! Я твой AI-наставник EDITA. Спроси меня про монтаж, портфолио или клиента."}]);
 const [input,setInput]=useState("");
 const [loading,setLoading]=useState(false);
 const [aiConfigured,setAiConfigured]=useState<boolean|null>(null);
 const [wins,setWins]=useState(0);
 const [businessStats,setBusinessStats]=useState({challenges:0,submissions:0,jobs:0});

 const xp=useMemo(()=>920+done.reduce((sum,slug)=>sum+(curriculum.find(l=>l.slug===slug)?.xp||0),0),[done]);
 const tabs=useMemo(()=>{
   if(viewer.role==="business") return allTabs.filter(([id])=>["home","coach","review","arena","community","profile","business"].includes(id));
   if(viewer.role==="editor") return allTabs.filter(([id])=>id!=="business");
   return allTabs;
 },[viewer.role]);

 useEffect(()=>{
   fetch("/api/ai/health").then(r=>r.json()).then(d=>setAiConfigured(Boolean(d.connected))).catch(()=>setAiConfigured(false));
   try{
     const raw=localStorage.getItem("edita_lesson_done");
     if(raw)setDone(JSON.parse(raw));
     const onboardingRaw=localStorage.getItem("edita_onboarding");
     if(onboardingRaw)setViewer(v=>({...v,onboarding:JSON.parse(onboardingRaw)}));
   }catch{}

   const supabase=getSupabaseBrowserClient();
   if(!supabase)return;
   let active=true;
   supabase.auth.getUser().then(async({data})=>{
     if(!active||!data.user)return;
     const {data:profile}=await supabase.from("profiles")
       .select("display_name,role,username,plan,plan_expires_at,ai_score,onboarding,earnings_cents,guardian_verified")
       .eq("id",data.user.id).single();
     if(!active)return;
     const {count:winsCount}=await supabase.from("challenge_submissions")
       .select("id",{count:"exact",head:true})
       .eq("editor_id",data.user.id)
       .eq("status","winner");
     setWins(winsCount||0);
     setViewer({
       name:profile?.display_name||data.user.user_metadata?.display_name||data.user.email?.split("@")[0]||"Пользователь",
       role:profile?.role==="business"?"business":"editor",
       username:profile?.username||null,
       plan:profile?.plan||"free",
       aiScore:profile?.ai_score||null,
       onboarding:profile?.onboarding||data.user.user_metadata?.onboarding||{},
       earningsCents:Number(profile?.earnings_cents||0),
       planExpiresAt:profile?.plan_expires_at||null,
       guardianVerified:Boolean(profile?.guardian_verified)
     });
     if(profile?.role==="business"){
       setTab("business");
       const {data:ownedBusiness}=await supabase.from("businesses").select("id").eq("owner_id",data.user.id).maybeSingle();
       if(ownedBusiness?.id){
         const {count:challengeCount}=await supabase.from("challenges").select("id",{count:"exact",head:true}).eq("business_id",ownedBusiness.id).eq("status","open");
         const {count:jobCount}=await supabase.from("jobs").select("id",{count:"exact",head:true}).eq("business_id",ownedBusiness.id).eq("status","open");
         const {data:ownedChallenges}=await supabase.from("challenges").select("id").eq("business_id",ownedBusiness.id);
         const ids=(ownedChallenges||[]).map((x:any)=>x.id);
         let submissionCount=0;
         if(ids.length){
           const {count}=await supabase.from("challenge_submissions").select("id",{count:"exact",head:true}).in("challenge_id",ids);
           submissionCount=count||0;
         }
         setBusinessStats({challenges:challengeCount||0,submissions:submissionCount,jobs:jobCount||0});
       }
     }
   });
   const {data:listener}=supabase.auth.onAuthStateChange((_event,session)=>{
     if(!session)setViewer({name:"Гость",role:null,onboarding:{}});
   });
   return()=>{active=false;listener.subscription.unsubscribe()};
 },[]);

 function toggleLesson(slug:string){
   setDone(current=>{
     const next=current.includes(slug)?current.filter(v=>v!==slug):[...current,slug];
     localStorage.setItem("edita_lesson_done",JSON.stringify(next));
     return next;
   });
 }

 async function signOut(){
   const supabase=getSupabaseBrowserClient();
   if(supabase)await supabase.auth.signOut();
   setViewer({name:"Гость",role:null,onboarding:{}});
   setTab("home");
 }

 async function ask(e:React.FormEvent){
   e.preventDefault();
   if(!input.trim()||loading)return;
   const q=input;
   setMessages(m=>[...m,{from:"user",text:q}]);
   setInput("");
   setLoading(true);
   try{
     const supabase=getSupabaseBrowserClient();
     const {data:{session}}=await supabase.auth.getSession();
     const headers:Record<string,string>={"Content-Type":"application/json"};
     if(session?.access_token)headers.Authorization="Bearer "+session.access_token;
     const r=await fetch("/api/ai",{
       method:"POST",
       headers,
       body:JSON.stringify({
         message:q,
         context:{
           level:viewer.onboarding?.level||"unknown",
           xp,
           editor:viewer.onboarding?.software||"CapCut",
           goal:viewer.onboarding?.goal||"freelance",
           role:viewer.role,
           completedLessons:done
         },
         history:messages
       })
     });
     const d=await r.json();
     setMessages(m=>[...m,{from:"ai",text:d.reply||"Не получилось ответить."}]);
   } finally {setLoading(false)}
 }

 const roleLabel=viewer.role==="business"?"Business":viewer.role==="editor"?"Editor":"Demo mode";
 const planLabel=viewer.plan==="pro"?"AI PRO":viewer.plan==="start"?"START":"FREE";

 return <main className="app">
   <aside className="side">
     <Link className="brand" href="/">EDITA<b>.</b></Link>
     <nav className="nav">{tabs.map(([id,l])=><button className={tab===id?"active":""} onClick={()=>setTab(id)} key={id}>{l}</button>)}</nav>
     <div className="profile">
       <b>{viewer.name}</b><br/>
       {roleLabel}{viewer.role==="editor"?" · "+planLabel:""}<br/>
       {viewer.role==="editor"&&<>{xp} XP<br/></>}
       {viewer.username&&<><Link href={"/u/"+viewer.username}>Публичное портфолио ↗</Link><br/></>}
       {viewer.role
         ? <button className="btn" onClick={signOut} style={{marginTop:10}}>Выйти</button>
         : <Link className="btn btn-lime" href="/onboarding" style={{marginTop:10}}>Начать</Link>}
     </div>
   </aside>

   <section className="main">
     <header className="head">
       <b className="mobile">EDITA.</b>
       <div className="user-pill"><span className="user-dot"/><span>{viewer.role?"online":"demo"} · {planLabel}{viewer.role==="editor"?" · "+xp+" XP":""}</span></div>
     </header>

     {tab==="home"&&<Page title={viewer.role?"Продолжай движение, "+viewer.name+".":"Добро пожаловать в EDITA."} sub={viewer.role?"Твой маршрут адаптируется под прогресс, программу и цель.":"Демо платформы. Пройди onboarding, чтобы получить персональный маршрут."}>
       <section className="mission"><small>МИССИЯ ДНЯ</small><h2>Hook за первые 2 секунды</h2><p>Собери 20-секундный Reel и сравни три версии первого кадра.</p><button className="btn btn-lime" onClick={()=>setTab("academy")}>Открыть обучение →</button></section>
       <div className="grid">
         <Card title="Твой рост"><div className="stats"><Stat n={viewer.aiScore!=null?String(viewer.aiScore):"—"} t="AI Score"/><Stat n={String(done.length)} t="уроков"/><Stat n={String(wins)} t="побед"/></div></Card>
         <Card title="Arena"><p className="muted">Открытые Challenge и training-задания появляются здесь после публикации бизнесом.</p><button className="btn btn-dark" onClick={()=>setTab("arena")}>Открыть Arena</button></Card>
         <Card title="Маршрут"><p className="muted">{viewer.onboarding?.software||"CapCut"} · {viewer.onboarding?.goal||"freelance"}</p><Link className="btn btn-ghost" href="/onboarding">Изменить цель</Link></Card>
       </div>
     </Page>}

     {tab==="academy"&&<Page title="Академия" sub={"Маршрут: "+(viewer.onboarding?.software||"CapCut")+" → "+(viewer.onboarding?.goal||"freelance")+". Реальные уроки + практика."}>
       <div className="grid">{curriculum.map((lesson,i)=><div className={"card lesson "+(done.includes(lesson.slug)?"done":"")} key={lesson.slug}>
         <div className="num">{done.includes(lesson.slug)?"✓":i+1}</div>
         <div><div className="eyebrow">{lesson.module}</div><h3>{lesson.title}</h3><p className="muted">{lesson.summary}</p>
           <div className="lesson-actions"><Link className="btn btn-dark" href={"/academy/"+lesson.slug}>Открыть</Link><button className="btn btn-ghost" onClick={()=>toggleLesson(lesson.slug)}>{done.includes(lesson.slug)?"Снять отметку":"+ "+lesson.xp+" XP"}</button></div>
         </div>
       </div>)}</div>
     </Page>}

     {tab==="practice"&&<Page title="Практика" sub="Симулятор реального клиента: цена, правки, сроки и переговоры."><ClientSimulator/></Page>}

     {tab==="coach"&&<Page title="AI Coach" sub="Наставник учитывает твою программу, цель и пройденные уроки.">
       <div className={"ai-status "+(aiConfigured?"online":"offline")}>{aiConfigured===null?"Проверяю AI…":aiConfigured?"● Live AI подключён":"● AI fallback mode"}</div>
       <div className="card chat"><div className="feed">{messages.map((m,i)=><div className={"bubble "+m.from} key={i}>{m.text}</div>)}{loading&&<div className="bubble">Разбираю…</div>}</div><form className="form" onSubmit={ask}><input value={input} onChange={e=>setInput(e.target.value)} placeholder="Почему мой Reel выглядит скучно?"/><button className="btn btn-lime">Спросить</button></form></div>
     </Page>}

     {tab==="review"&&<Page title="AI Video Review" sub="Загрузи ролик и получи структурированный разбор по кадрам и таймкодам.">{viewer.role==="editor"&&viewer.plan!=="pro"?<UpgradePro/>:<VideoReview/>}</Page>}
     {tab==="arena"&&<Page title="Arena" sub="Реальные ТЗ, одинаковые исходники, реальные призы."><ChallengeCenter role={viewer.role} viewerName={viewer.name} ageGroup={viewer.onboarding?.ageGroup} guardianVerified={viewer.guardianVerified} mode="arena"/></Page>}

     {tab==="portfolio"&&<Page title={viewer.role==="editor"?viewer.name:"Публичное портфолио"} sub="Verified Editor · Skill Graph · реальные работы">
       <PortfolioPanel/>
       <div style={{marginTop:14}}>{viewer.username?<Link className="btn btn-dark" href={"/u/"+viewer.username}>Открыть публичный URL</Link>:<Link className="btn btn-dark" href="/u/demo">Посмотреть demo-портфолио</Link>}</div>
     </Page>}

     {tab==="wallet"&&<Page title="Wallet" sub="Доход внутри EDITA, покупки и доступы.">
       <div className="grid">
         <Card title="Заработано"><div className="wallet-number">{money(viewer.earningsCents||0)}</div><p className="muted">Доход от проектов и Challenge после подключения production-выплат.</p></Card>
         <Card title="Текущий доступ"><div className="wallet-number">{planLabel}</div><p className="muted">{viewer.planExpiresAt?"До "+new Date(viewer.planExpiresAt).toLocaleDateString("ru-RU"):"Без активного срока AI PRO"}</p><Link className="btn btn-dark" href="/pricing">Управлять доступом</Link></Card>
         <Card title="Платежи"><p className="muted">История покупок и выплат появится здесь после одобрения платёжного магазина и первых транзакций.</p></Card>
       </div>
     </Page>}

     {tab==="profile"&&<Page title="Профиль" sub="Skill Graph, персональный маршрут и публичная карьерная карточка.">
       <div className="profile-grid">
         <Card title="Career Passport"><p><b>{viewer.name}</b></p><p className="muted">{viewer.onboarding?.software||"CapCut"} · {viewer.onboarding?.goal||"freelance"} · {planLabel}</p>{viewer.username&&<Link className="btn btn-dark" href={"/u/"+viewer.username}>Публичный профиль ↗</Link>}</Card>
         <Card title="Skill Graph"><Skill label="Монтаж" value={Math.min(100,55+done.length*5)}/><Skill label="Hook / retention" value={Math.min(100,50+done.filter(s=>["hook-2-seconds","subtitles","b-roll"].includes(s)).length*12)}/><Skill label="Client work" value={Math.min(100,45+done.filter(s=>["client-brief","pricing","portfolio"].includes(s)).length*15)}/></Card>
         <Card title="Настройки маршрута"><p className="muted">Уровень: {viewer.onboarding?.level||"не указан"}<br/>Софт: {viewer.onboarding?.software||"не указан"}<br/>Цель: {viewer.onboarding?.goal||"не указана"}</p><Link className="btn btn-ghost" href="/onboarding">Изменить onboarding</Link></Card>
       </div>
     </Page>}

     {tab==="jobs"&&<Page title="Работа" sub="Вакансии подбираются по навыкам и подтверждённым работам."><JobBoard mode="editor"/></Page>}
     {tab==="community"&&<Page title="Community" sub="Публичный рейтинг строится только на безопасных карьерных данных."><CommunityLeaderboard/></Page>}
     {tab==="business"&&<Page title="Business Workspace" sub="Создавайте задания, храните контекст бренда и нанимайте по реальному результату."><div className="business-grid"><Stat n={String(businessStats.challenges)} t="активных Challenge"/><Stat n={String(businessStats.submissions)} t="получено работ"/><Stat n={String(businessStats.jobs)} t="открытых вакансий"/><Stat n="BETA" t="режим workspace"/></div><div className="business-stack"><BrandBrain viewerName={viewer.name}/><ChallengeCenter role={viewer.role} viewerName={viewer.name} ageGroup={viewer.onboarding?.ageGroup} guardianVerified={viewer.guardianVerified} mode="business"/><JobBoard mode="business" viewerName={viewer.name}/></div></Page>}
   </section>

   <nav className="mobile-nav">{tabs.map(([id,l])=><button key={id} className={tab===id?"active":""} onClick={()=>setTab(id)}>{l}</button>)}</nav>
 </main>
}

function Page({title,sub,children}:{title:string;sub:string;children:React.ReactNode}){return <div className="page"><h1>{title}</h1><p className="sub">{sub}</p>{children}</div>}
function Card({title,children}:{title:string;children:React.ReactNode}){return <div className="card"><h3>{title}</h3>{children}</div>}
function Stat({n,t}:{n:string;t:string}){return <div className="stat"><strong>{n}</strong><span className="muted">{t}</span></div>}
function Job({title,pay}:{title:string;pay:string}){return <div className="card job"><small>REMOTE</small><h3>{title}</h3><p className="muted">Проверенный бизнес · подбор по portfolio score</p><b>{pay}</b><button className="btn btn-dark">Податься</button></div>}

function UpgradePro(){return <div className="upgrade-card"><div className="eyebrow">AI PRO</div><h2>AI Video Review входит в PRO</h2><p>Персональный разбор по кадрам, таймкодам, hook, pacing, субтитрам и соответствию ТЗ.</p><Link className="btn btn-lime" href="/pricing">Подключить AI PRO · 499 ₽ / 30 дней</Link></div>}
function Skill({label,value}:{label:string;value:number}){return <div className="skill-row"><div><span>{label}</span><b>{value}</b></div><div className="score-track"><span style={{width:value+"%"}}/></div></div>}
function money(cents:number){return new Intl.NumberFormat("ru-RU",{style:"currency",currency:"RUB",maximumFractionDigits:0}).format(cents/100)}

"use client";

import {FormEvent,useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type Item={id:string;title:string;video_url:string;display_url?:string;tags:string[];ai_score:number|null};

const demo:Item[]=[
  {id:"d1",title:"VOLT / Gym Promo",video_url:"",tags:["ads","reels"],ai_score:91},
  {id:"d2",title:"Finance Expert Reel",video_url:"",tags:["talking-head"],ai_score:86},
  {id:"d3",title:"North Coffee",video_url:"",tags:["challenge-winner"],ai_score:90},
];

export default function PortfolioPanel(){
  const [items,setItems]=useState<Item[]>([]);
  const [demoMode,setDemoMode]=useState(false);
  const [form,setForm]=useState({title:"",url:"",tags:""});
  const [message,setMessage]=useState("");

  useEffect(()=>{void load()},[]);

  async function load(){
    const supabase=getSupabaseBrowserClient();
    if(!supabase){setItems(demo);setDemoMode(true);return;}
    const {data:{user}}=await supabase.auth.getUser();
    if(!user){setItems(demo);setDemoMode(true);return;}

    const {data,error}=await supabase.from("portfolio_items").select("id,title,video_url,tags,ai_score").eq("editor_id",user.id).order("created_at",{ascending:false});
    if(error){setMessage(error.message);return;}
    const rows=(data||[]) as Item[];
    const mapped=await Promise.all(rows.map(async item=>{
      if(/^https?:\/\//.test(item.video_url))return {...item,display_url:item.video_url};
      const {data:signed}=await supabase.storage.from("challenge-submissions").createSignedUrl(item.video_url,60*60);
      return {...item,display_url:signed?.signedUrl||""};
    }));
    setItems(mapped);
  }

  async function add(e:FormEvent){
    e.preventDefault();
    const supabase=getSupabaseBrowserClient();
    if(!supabase){setMessage("В demo работа не сохраняется. После подключения Auth она попадёт в публичный профиль.");return;}
    const {data:{user}}=await supabase.auth.getUser();
    if(!user){setMessage("Войди в аккаунт, чтобы добавить работу.");return;}
    const tags=form.tags.split(",").map(v=>v.trim()).filter(Boolean);
    const {error}=await supabase.from("portfolio_items").insert({editor_id:user.id,title:form.title,video_url:form.url,tags});
    if(error){setMessage(error.message);return;}
    setForm({title:"",url:"",tags:""});setMessage("Работа добавлена.");
    await load();
  }

  return <div className="portfolio-panel">
    <section className="card">
      <div className="eyebrow">ADD WORK</div><h3>Добавить работу в портфолио</h3>
      <form className="business-form" onSubmit={add}>
        <input required placeholder="Название работы" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/>
        <input required type="url" placeholder="Ссылка на видео (YouTube/Vimeo/Drive/прямая ссылка)" value={form.url} onChange={e=>setForm({...form,url:e.target.value})}/>
        <input placeholder="Теги через запятую: reels, ads, talking-head" value={form.tags} onChange={e=>setForm({...form,tags:e.target.value})}/>
        <button className="btn btn-dark">Добавить</button>
      </form>
      {message&&<div className="auth-msg">{message}</div>}
      {demoMode&&<p className="muted">Сейчас показан demo fallback.</p>}
    </section>

    <section className="portfolio-work-grid portfolio-live-grid">
      {items.length?items.map(item=><article className="portfolio-work" key={item.id}>
        <div className="work-preview">{item.display_url&&isDirectVideo(item.display_url)?<video controls preload="metadata" src={item.display_url}/>:<span>EDITA WORK</span>}</div>
        <h2>{item.title}</h2>
        <div className="work-meta"><span>{item.tags.join(" · ")}</span>{item.ai_score!=null&&<b>AI {item.ai_score}</b>}</div>
        {item.display_url&&!isDirectVideo(item.display_url)&&<a className="work-link" href={item.display_url} target="_blank" rel="noreferrer">Открыть работу ↗</a>}
      </article>):<div className="card"><p>Добавь первую работу или выиграй Challenge — она появится здесь.</p></div>}
    </section>
  </div>
}

function isDirectVideo(url:string){return /\.(mp4|webm|mov)(\?|$)/i.test(url)||url.includes("supabase")}

